lock}.reference-number{color:var(--bs-primary);font-size:.75rem}.cell-main,.cell-text{font-size:.72rem}.cell-sub{color:#8491a0;font-size:.62rem}.priority,.status{display:inline-flex;align-items:center;gap:.3rem;padding:.28rem .5rem;border-radius:20px;background:color-mix(in srgb,var(--status) 13%,white);color:var(--status);font-size:.62rem;font-weight:700}.status i{font-size:.4rem}.empty{text-align:center;padding:4rem;color:#718096}.empty i{font-size:2.8rem;color:#a9bfce}.empty h3{margin:.7rem 0 .2rem;font-size:1rem}@media(max-width:991px){.metric-grid{grid-template-columns:repeat(2,1fr)}.referral-hero{align-items:flex-start;flex-direction:column}}@media(max-width:575px){.metric-grid{grid-template-columns:1fr}.hero-actions{width:100%;flex-direction:column}.results-card .card-header{align-items:flex-start;flex-direction:column;gap:.7rem}.local-search,.local-search input{width:100%}}
</style>
